                let (l, _) = line_col(self.src, self.pos);
                let mut ls = self.pos;
                while ls > 0 && self.src[ls - 1] != b'\n' {
                    ls -= 1;
                }
                self.line = l;
                self.line_start = ls;
                self.space = true;
            }
