            }
            _ => {
                if let Some(id) = id {
                    send(&Json::obj(vec![
                        ("jsonrpc", Json::str("2.0")),
                        ("id", id.clone()),
                        ("error", Json::obj(vec![("code", Json::int(-32601)), ("message", Json::str("method not found"))])),
                    ]));
                }
            }
        }
    }
