//! `pyfun add`, `pyfun install` and `pyfun remove`: façade dependencies
//! (`DESIGN.md` §6.2).
//!
//! A façade is an ordinary pip distribution that ships typed `extern`
//! declarations as `.pyfun` files. `add` installs it with the environment's own
//! installer (`uv pip` when `uv` is on PATH, else `python -m pip`), copies its
//! `.pyfun` files into `<root>/.pyfun/facades/<dist>/`, and records the installed
//! version in `pyfun.toml`; `install` does the same for every dependency the
//! manifest lists, pinned to its recorded version. The compiler reads only the
//! vendored copies, so checking and compiling stay offline.

use std::path::{Path, PathBuf};
use std::process::{Command, ExitCode};

use pyfun::project::manifest;

/// `pyfun add <requirement>...`
pub fn add(specs: &[String]) -> ExitCode {
    if specs.is_empty() {
        return fail("`add` needs a package, e.g. `pyfun add pyfun-textwrap`");
    }
    let root = match project_root(true) {
        Ok(root) => root,
        Err(msg) => return fail(&msg),
    };
    for spec in specs {
        let dist = match dist_name(spec) {
            Ok(dist) => dist,
            Err(msg) => return fail(&msg),
        };
        if let Err(msg) = install_and_vendor(&root, spec, &dist) {
            return fail(&msg);
        }
    }
    ExitCode::SUCCESS
}

/// `pyfun install`: every dependency in `pyfun.toml`, at its recorded version.
pub fn install() -> ExitCode {
    let root = match project_root(false) {
        Ok(root) => root,
        Err(msg) => return fail(&msg),
    };
    let text = std::fs::read_to_string(root.join(manifest::MANIFEST)).unwrap_or_default();
    let deps = manifest::table(&text, "dependencies");
    if deps.is_empty() {
        println!("no dependencies in {}", manifest::MANIFEST);
        return ExitCode::SUCCESS;
    }
    for (dist, version) in deps {
        let spec = if version.is_empty() {
            dist.clone()
        } else {
            format!("{dist}=={version}")
        };
        if let Err(msg) = install_and_vendor(&root, &spec, &dist) {
            return fail(&msg);
        }
    }
    ExitCode::SUCCESS
}

/// `pyfun remove <package>...`: drop each from `pyfun.toml`, delete its vendored
/// façade, and uninstall it from the environment.
pub fn remove(dists: &[String]) -> ExitCode {
    if dists.is_empty() {
        return fail("`remove` needs a package name");
    }
    let root = match project_root(false) {
        Ok(root) => root,
        Err(msg) => return fail(&msg),
    };
    let manifest_path = root.join(manifest::MANIFEST);
    let mut text = std::fs::read_to_string(&manifest_path).unwrap_or_default();
    for dist in dists {
        let (updated, removed) = manifest::remove(&text, "dependencies", dist);
        if !removed {
            return fail(&format!(
                "`{dist}` is not a dependency in {}",
                manifest::MANIFEST
            ));
        }
        text = updated;
        let vendored = root
            .join(manifest::FACADES)
            .join(manifest::normalize_dist(dist));
        let _ = std::fs::remove_dir_all(&vendored);
        if let Some(python) = crate::python_cmd() {
            let uv = Command::new("uv").arg("--version").output().is_ok();
            let _ = if uv {
                Command::new("uv")
                    .args(["pip", "uninstall", "--python", &python, dist])
                    .status()
            } else {
                Command::new(&python)
                    .args(["-m", "pip", "uninstall", "-y", dist])
                    .status()
            };
        }
        println!("removed {dist}");
    }
    if let Err(e) = std::fs::write(&manifest_path, text) {
        return fail(&format!("cannot write {}: {e}", manifest_path.display()));
    }
    ExitCode::SUCCESS
}

/// The project root: the nearest `pyfun.toml` at or above the working
/// directory. `add` creates one in the working directory when there is none.
fn project_root(create: bool) -> Result<PathBuf, String> {
    let cwd =
        std::env::current_dir().map_err(|e| format!("cannot read the working directory: {e}"))?;
    if let Some(root) = manifest::find_root(&cwd) {
        return Ok(root);
    }
    if !create {
        return Err(format!(
            "no {} here or in any parent directory (`pyfun add <package>` creates one)",
            manifest::MANIFEST
        ));
    }
    let name = cwd
        .file_name()
        .map(|n| n.to_string_lossy().to_string())
        .unwrap_or_else(|| "project".to_string());
    std::fs::write(cwd.join(manifest::MANIFEST), manifest::new_manifest(&name))
        .map_err(|e| format!("cannot write {}: {e}", manifest::MANIFEST))?;
    println!("created {}", manifest::MANIFEST);
    Ok(cwd)
}

/// The distribution a requirement names. A name with an optional version
/// specifier is read directly; a local directory is read from its
/// `pyproject.toml`'s `[project] name`.
fn dist_name(spec: &str) -> Result<String, String> {
    let path = Path::new(spec);
    if path.is_dir() {
        let text = std::fs::read_to_string(path.join("pyproject.toml"))
            .map_err(|_| format!("`{spec}` is a directory with no pyproject.toml"))?;
        return manifest::table(&text, "project")
            .into_iter()
            .find(|(k, _)| k == "name")
            .map(|(_, v)| v)
            .ok_or_else(|| format!("`{spec}/pyproject.toml` has no [project] name"));
    }
    let end = spec
        .find(['=', '<', '>', '!', '~', ';', '[', ' ', '@'])
        .unwrap_or(spec.len());
    let name = spec[..end].trim();
    if name.is_empty() {
        return Err(format!("cannot read a package name from `{spec}`"));
    }
    Ok(name.to_string())
}

fn install_and_vendor(root: &Path, spec: &str, dist: &str) -> Result<(), String> {
    let python = crate::python_cmd().ok_or("no Python interpreter found (set PYFUN_PYTHON)")?;
    run_installer(&python, spec)?;
    let (version, files) = facade_files(&python, dist)?;
    if files.is_empty() {
        return Err(format!(
            "`{dist}` installed, but it ships no .pyfun files, so it is not a Pyfun façade"
        ));
    }
    let target = root
        .join(manifest::FACADES)
        .join(manifest::normalize_dist(dist));
    let _ = std::fs::remove_dir_all(&target);
    std::fs::create_dir_all(&target)
        .map_err(|e| format!("cannot create {}: {e}", target.display()))?;
    let mut modules = Vec::new();
    for file in &files {
        let name = file
            .file_name()
            .ok_or_else(|| format!("odd façade path {}", file.display()))?;
        std::fs::copy(file, target.join(name))
            .map_err(|e| format!("cannot copy {}: {e}", file.display()))?;
        if let Some(module) = pyfun::project::module_name_from_path(Path::new(name)) {
            modules.push(module);
        }
    }
    let manifest_path = root.join(manifest::MANIFEST);
    let text = std::fs::read_to_string(&manifest_path).unwrap_or_default();
    let text = manifest::set(&text, "dependencies", dist, &version);
    std::fs::write(&manifest_path, text)
        .map_err(|e| format!("cannot write {}: {e}", manifest_path.display()))?;
    modules.sort();
    println!("added {dist} {version} (import {})", modules.join(", "));
    Ok(())
}

/// Install `spec` into the interpreter's environment: `uv pip` when `uv` is on
/// PATH (pointed at that interpreter), else `python -m pip`.
fn run_installer(python: &str, spec: &str) -> Result<(), String> {
    let uv = Command::new("uv").arg("--version").output().is_ok();
    let status = if uv {
        Command::new("uv")
            .args(["pip", "install", "--python", python, spec])
            .status()
    } else {
//! Pyfun — an FP-first language that compiles to Python.
//!
//! Phase 1 scaffolding: the front-end pipeline entry points wired together.
//! See `DESIGN.md` for the full architecture and roadmap.
//!
//! Pipeline implemented so far: source → [`lexer`] → tokens → [`parser`] → AST
//! → [`lowering`] → Python IR → [`python_emitter`] → Python source. The
//! pretty-printer ([`ast`]) drives the parse→print→parse roundtrip tests.

pub mod ast;
pub mod desugar;
pub mod diagnostics;
pub mod lexer;
pub mod lowering;
pub mod lsp;
pub mod parser;
pub mod project;
pub mod python_emitter;
pub mod types;

pub use parser::ast as syntax;

/// The compiler version, so an embedder can report which one it is running.
/// `pyfun version` reads the same constant through the binary crate, and the
/// WebAssembly playground shows it in the page footer.
pub const VERSION: &str = env!("CARGO_PKG_VERSION");

/// Lex and parse `source` into a [`syntax::Module`].
///
/// This is the convenience entry point used by the CLI and tests. Lexing and
/// parsing errors are surfaced as a single [`CompileError`].
pub fn parse(source: &str) -> Result<syntax::Module, CompileError> {
    let tokens = lexer::lex(source).map_err(CompileError::Lex)?;
    parser::parse(tokens).map_err(CompileError::Parse)
}

/// Lex, parse, then pretty-print `source` back to canonical Pyfun text.
///
/// The printer fully parenthesizes compound expressions, so its output is
/// canonical rather than a faithful reproduction of the original formatting.
pub fn format(source: &str) -> Result<String, CompileError> {
    Ok(ast::print_module(&parse(source)?))
}

/// Type-check `source`, returning every type error found.
///
/// A parse failure is reported as a single error in the returned vector.
pub fn check(source: &str) -> Result<(), Vec<types::TypeError>> {
    let module = parse(source).map_err(|e| vec![to_type_error(&e)])?;
    types::check(&module)
}

/// A resilient analysis of a source document, for the editor (the LSP,
/// `DESIGN.md` §9). Produced by [`analyze`] and consumed by every LSP feature.
///
/// "Resilient" means a half-typed file still yields results: parsing recovers at
/// item boundaries, so the items that *do* parse populate `module` (and its hover
/// `types` and navigation), while the broken ones surface as `diagnostics`.
pub struct Analysis {
    /// The recovered module. Always present (lexing and parsing both recover), but
    /// may be *partial* — missing items that did not parse — when `parse_ok` is
    /// false. Kept an `Option` so the API tolerates a future fatal-parse path.
    pub module: Option<syntax::Module>,
    /// Diagnostics to publish: syntax errors (lex + parse) when the file does not
    /// fully parse, otherwise the type/effect/unit errors.
    pub diagnostics: Vec<types::TypeError>,
    /// The span→type table for hover (best-effort, even for a partial module).
    pub types: Vec<types::TypeSpan>,
    /// Typed holes (`?` / `?name`) and their inferred types — surfaced by the LSP
    /// at `Information` severity (an intentional blank, not an error).
    pub holes: Vec<types::Hole>,
    /// Whether the document lexed and parsed with no syntax errors. Mutating
    /// features (rename) require this — a partial module could hide occurrences.
    pub parse_ok: bool,
}

/// Analyze `source` for the editor (the LSP, `DESIGN.md` §9).
